INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'მონიტორი', '["მონიტორები","monitori","monitorebi","монитор","კომპიუტერის მონიტორი","კომპიუტერის ეკრანი"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'მონიტორი');
INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'მონიტორები' AS word UNION ALL SELECT 'monitori' UNION ALL SELECT 'monitorebi' UNION ALL SELECT 'монитор' UNION ALL SELECT 'კომპიუტერის მონიტორი' UNION ALL SELECT 'კომპიუტერის ეკრანი' UNION ALL SELECT 'მონიტორი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);
