-- ============================================================================
-- superi.ge — 42: „მონიტორები“ (/monitor/) — კატეგორიის სრული მოწესრიგება, 106 პროდუქტი
-- 1) კატეგორია: ძველი ერთწინადადებიანი ტექსტის ნაცვლად სრული გზამკვლევი (~580 სიტყვა): ზომა და გარჩევადობა,
--    Hz, IPS / VA / OLED, მოხრილი, პორტები, ერგონომიკა, პოპულარული მოდელები, კითხვა-პასუხი + მეტა აღწერა.
-- 2) 106 პროდუქტის სახელი ერთ ფორმაზე: „მონიტორი Brand Model ზომა" გარჩევადობა (კოდი), ფერი“.
--    გასწორდა შეცდომები: Lenovo Legion Pro 32UD-10 „ნოუთბუქი“ ეწერა; Samsung Odyssey G8 34" და Xiaomi G34WQi — „4K“
--    (სინამდვილეში WQHD 3440×1440); Odyssey G9 49" — „5K“ (DQHD); Odyssey G5 32" — „DQHD“ (2K).
--    სათაური (page title) მხოლოდ იქ იცვლება, სადაც ძველი სახელის ზუსტი ასლი იყო — ახალი სახელით, იგივე ფორმატით.
-- 3) 106 უნიკალური მეტა აღწერა: ზომა, გარჩევადობა, პანელი, Hz, რეაგირება, დანიშნულება (160 სიმბოლომდე).
-- 4) აღწერები: Odyssey G8 — „4K UHD (3440 x 1440)“ → UWQHD, პანელი VA → QD-OLED; Xiaomi G34WQi — „4K“ და
--    „მოსახედი პანელი“; Odyssey G4 27" (LS27BG400) — 144 Hz → 240 Hz (აღწერაში ორივე ეწერა).
-- 5) 13 გრძელი/შეცდომიანი მისამართი (მაგ. monitor-lenovo-lenovo-legion-…-raven-black-type-c, …-g8-34-4k-…)
--    → მოკლე და სწორი; ძველი 301-ით გადადის ახალზე.
-- 6) ძებნის სინონიმები: მონიტორები, монитор, გეიმერული მონიტორი, gaming monitor, მრუდე / curved მონიტორი…
-- 7) ბრენდის სახელს „ACER “ ბოლოში ზედმეტი ჰარი ჰქონდა (Product schema-შიც) → „ACER“.
-- 8) 41-ის დარჩენილი 2 ბმული (BOSCH, INTEX) მოკლე აღწერაში → პირდაპირ სწორ მისამართზე.
-- ასლები: superi_bk_cat_42, superi_bk_prod_42, superi_bk_seo_42, superi_bk_red_42, superi_bk_fv_42. ხელახლა გაშვება უსაფრთხოა.
-- დაბრუნება ბოლოშია. ატვირთვის შემდეგ: Live search → Synonyms → „Rebuild synonym index“ → ქეშის გასუფთავება.
-- ============================================================================
SET NAMES utf8mb4;
SET @f := (SELECT src FROM cscart_seo_redirects WHERE TRIM(BOTH '/' FROM src) = 'category-15' LIMIT 1);
SET @pre := IF(@f IS NULL OR LEFT(@f,1) = '/', '/', '');
SET @post := IF(@f IS NULL OR RIGHT(@f,1) = '/', '/', '');

-- 0) ასლები (მხოლოდ პირველ გაშვებაზე)
CREATE TABLE IF NOT EXISTS superi_bk_cat_42 AS SELECT cd.category_id, cd.lang_code, cd.description, cd.meta_description FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'monitor' WHERE cd.lang_code = 'ka';
