CREATE TABLE IF NOT EXISTS superi_bk_seo_42 AS SELECT * FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name IN ('monitor-asus-asus-rog-swift-oled-pg27ucdm-qd-oled-27-3840-x-2160-240hz-0-03ms', 'monitor-hp-hp-series-7-pro-732xk-31-5-3840-x-2160-ips-450-nits-5ms', 'monitor-lenovo-lenovo-legion-pro-27ud-10-qd-oled-250-cd-m-3840x2160-240hz-raven-black-type-c', 'monitor-lenovo-lenovo-legion-r45w-30-curved-44-5-5120x1440-va-450-cd-m-4ms-165hz-170hz-overc', 'monitor-lenovo-lenovo-thinkvision-p40wd-40-curved-39-7-wuhd-5120x2160-4ms-120-hz-eclipse-black', 'monitor-lenovo-lenovo-yoga-pro-27ud-10-monitor-26-5-3840-x-2160-qd-oled-0-03-ms-120hz-eclipse-bla', 'monitor-samsung-odyssey-g5-ls32fg502eixci-32-qhd-2560x1440-ips-1ms-180hz', 'monitor-samsung-viewfinity-s7-ls32h700eaixci-32-4k-3840-x-2160-ips-5ms-60hz-black', 'samsung-viewfinity-s9-va-ls49c950uaixci-49-curved-dqhd-5120-x-1440-5ms-120hz', 'lenovo-legion-r27qe-gen-2-27-ips-2560x1440-400-cd-m-0-5ms-200hz-black', 'samsung-odyssey-g8-34-4k-smart-ls34dg852sixci-silver', 'samsung-odyssey-g9-49-5k-ls49dg932sixci-silver', 'lenovo-67bckac6eu-23-8');
CREATE TABLE IF NOT EXISTS superi_bk_red_42 AS SELECT * FROM cscart_seo_redirects WHERE company_id = 1 AND TRIM(BOTH '/' FROM src) IN ('asus-rog-swift-oled-pg27ucdm', 'hp-series-7-pro-732xk', 'lenovo-legion-pro-27ud-10', 'lenovo-legion-r45w-30', 'lenovo-thinkvision-p40wd-40', 'lenovo-yoga-pro-27ud-10', 'samsung-odyssey-g5-ls32fg502eixci', 'samsung-viewfinity-s7-ls32h700eaixci', 'samsung-viewfinity-s9-ls49c950uaixci', 'lenovo-legion-r27qe-gen-2', 'samsung-odyssey-oled-g8-ls34dg852sixci', 'samsung-odyssey-oled-g9-ls49dg932sixci', 'lenovo-l24i-4a-67bckac6eu');
CREATE TABLE IF NOT EXISTS superi_bk_fv_42 AS SELECT variant_id, lang_code, variant FROM cscart_product_feature_variant_descriptions WHERE TRIM(variant) = 'ACER' AND CHAR_LENGTH(variant) > 4;

-- 1) კატეგორია: ტექსტი და მეტა აღწერა
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'monitor' SET cd.description = '<p><strong>მონიტორი</strong> კომპიუტერის ის ნაწილია, რომელსაც ყველაზე მეტ დროს უყურებთ — ამიტომ სწორი არჩევანი თვალის კომფორტზეც მოქმედებს და მუშაობის ან თამაშის სიამოვნებაზეც. Superi.ge-ზე 100-ზე მეტი მონიტორია 22-დან 57 დიუმამდე: ოფისისა და სახლის Full HD მოდელები, 2K და 4K მონიტორები სამუშაოსა და დიზაინისთვის, 144–360 Hz გეიმინგ მონიტორები, OLED და მოხრილი ultrawide ეკრანები — <a href="https://superi.ge/samsung/">Samsung</a>, <a href="https://superi.ge/lg/">LG</a>, <a href="https://superi.ge/dell/">Dell</a>, <a href="https://superi.ge/asus/">ASUS</a>, <a href="https://superi.ge/lenovo/">Lenovo</a>, <a href="https://superi.ge/hp/">HP</a>, <a href="https://superi.ge/xiaomi/">Xiaomi</a>, <a href="https://superi.ge/tcl/">TCL</a>, <a href="https://superi.ge/viewsonic/">ViewSonic</a> და სხვა ბრენდები.</p><h2>როგორ შევარჩიოთ მონიტორი</h2><ul><li><strong>ზომა და გარჩევადობა</strong> ერთად უნდა შეარჩიოთ: 24" მონიტორზე Full HD (1920×1080) საკმარისია, 27"-ზე საუკეთესო ბალანსია 2K (2560×1440), 32"-ზე კი 4K (3840×2160) — ასე გამოსახულება მკვეთრი რჩება. 34" ultrawide (3440×1440) ორი ფანჯრის გვერდიგვერდ გახსნისთვისაა.</li><li><strong>განახლების სიხშირე (Hz):</strong> ოფისისა და ფილმებისთვის 60–100 Hz საკმარისია; თამაშისთვის აირჩიეთ 144–180 Hz, კონკურენტული (e-sports) თამაშებისთვის კი 240–360 Hz. რაც მეტია Hz, მით უფრო გლუვია მოძრაობა.</li><li><strong>პანელის ტიპი:</strong> IPS — ზუსტი ფერები და კარგი ხედვის კუთხე; VA — მაღალი კონტრასტი და ღრმა შავი, ხშირად მოხრილ მოდელებში; OLED / QD-OLED — სრულყოფილი შავი და 0.03 მწ რეაგირება; Mini LED — მაღალი სიკაშკაშე HDR-ისთვის.</li><li><strong>ბრტყელი თუ მოხრილი:</strong> 24–27"-ზე ბრტყელი ეკრანი სავსებით კარგია, 32" და მეტ ზომაზე, განსაკუთრებით ultrawide-ზე, მოხრილი (Curved) ეკრანი თვალს ნაკლებად ღლის და კიდეებს უკეთ ხედავთ.</li><li><strong>პორტები:</strong> HDMI ყველა მონიტორს აქვს; 144 Hz-ზე მეტი სიხშირისთვის სასურველია DisplayPort. USB-C პორტით ლეპტოპს ერთი კაბელით შეაერთებთ და დატენავთ კიდეც.</li><li><strong>ერგონომიკა:</strong> სიმაღლისა და დახრის რეგულირება, VESA სამაგრი კედელზე ან ქრონშტეინზე და თვალის დაცვის რეჟიმი (Flicker-Free, Low Blue Light) — მნიშვნელოვანია, თუ მონიტორთან დღეში რამდენიმე საათს ატარებთ.</li></ul><h2>პოპულარული მონიტორები</h2><ul><li><strong>გეიმინგ მონიტორები:</strong> <a href="https://superi.ge/samsung-odyssey-g5-27-2k-ls27fg502eixci-black/">Samsung Odyssey G5 27" 2K 180 Hz</a>, <a href="https://superi.ge/lg-ultragear-gaming-27-2k-27g610a-b-black/">LG UltraGear 27G610A 2K 200 Hz</a>, <a href="https://superi.ge/asus-tuf-gaming-monitor-27vg279q3a-fhd-180hz/">ASUS TUF VG279Q3A 180 Hz</a>, <a href="https://superi.ge/dell-alienware-aw2725dm-27-2k/">Dell Alienware AW2725DM</a>, <a href="https://superi.ge/tcl-g64-24-5-fhd-25g64-graphite-gray/">TCL G64 25" 300 Hz</a>.</li><li><strong>OLED მონიტორები:</strong> <a href="https://superi.ge/samsung-odyssey-oled-g6-g60sd-ls27dg600sixci/">Samsung Odyssey OLED G6 360 Hz</a>, <a href="https://superi.ge/lg-27-27gs95qe-b-ultragear-oled-gaming/">LG UltraGear OLED 27GS95QE</a>, <a href="https://superi.ge/asus-rog-swift-oled-pg27ucdm/">ASUS ROG Swift PG27UCDM 4K</a>, <a href="https://superi.ge/lenovo-legion-pro-32ud-10-31-5-4k-69d0gacbeu-white/">Lenovo Legion Pro 32UD-10</a>.</li><li><strong>ოფისისა და სახლისთვის:</strong> <a href="https://superi.ge/dell-p2425h-23-8-fhd/">Dell P2425H</a>, <a href="https://superi.ge/samsung-essential-s3-ls27d300gaixci-27-fhd/">Samsung Essential S3 27"</a>, <a href="https://superi.ge/lenovo-thinkvision-t24-40-23-8-fhd-64a4matxeu-black/">Lenovo ThinkVision T24-40</a>, <a href="https://superi.ge/xiaomi-a27i-ela5345eu/">Xiaomi A27i</a>, <a href="https://superi.ge/hp-series-5-pro-527pq-27-2k/">HP Series 5 Pro 527pq 2K</a>.</li><li><strong>4K და 5K — სამუშაოსა და დიზაინისთვის:</strong> <a href="https://superi.ge/samsung-viewfinity-s7-27-4k-ls27d700eaixci-black/">Samsung ViewFinity S7 27" 4K</a>, <a href="https://superi.ge/dell-ultrasharp-u2724d-27-2k/">Dell UltraSharp U2724D</a>, <a href="https://superi.ge/lenovo-thinkvision-t27ud-40-27-4k-64afgat2eu-eclipse-black/">Lenovo ThinkVision T27UD-40</a>, <a href="https://superi.ge/lg-smart-monitor-4k-uhd-32-32u850sa-w/">LG Smart Monitor 32U850SA</a>, <a href="https://superi.ge/samsung-27-viewfinity-s9-ls27c902paixci/">Samsung ViewFinity S9 5K</a>.</li><li><strong>მოხრილი და ultrawide:</strong> <a href="https://superi.ge/samsung-34-odyssey-g5-curved-lc34g55twwixci-black/">Samsung Odyssey G5 34"</a>, <a href="https://superi.ge/lg-ultragear-curved-34-wqhd-34g600a-b-ama-black/">LG UltraGear 34G600A</a>, <a href="https://superi.ge/xiaomi-curved-gaming-monitor-g34wqi-34-c34wqba-rggl/">Xiaomi G34WQi</a>, <a href="https://superi.ge/samsung-odyssey-oled-g9-ls49dg932sixci/">Samsung Odyssey OLED G9 49"</a>, <a href="https://superi.ge/samsung-odyssey-neo-g9-57-dual-4k-uhd-ls57cg952nixci-black-white/">Samsung Odyssey Neo G9 57"</a>.</li></ul><p>დეტალური გზამკვლევი — <a href="https://superi.ge/rogor-shevarchiot-monitori/">როგორ შევარჩიოთ მონიტორი</a>. მონიტორთან ერთად შეარჩიეთ <a href="https://superi.ge/mausebi/">მაუსი</a>, <a href="https://superi.ge/kompiuteris-aqsesuarebi/">კომპიუტერის აქსესუარები</a> და <a href="https://superi.ge/gaming/">გეიმინგ მაგიდა-სავარძელი</a>; თუ ლეპტოპი გჭირდებათ, იხილეთ <a href="https://superi.ge/noutbuqebi/">ნოუთბუქები</a>.</p><h2>ხშირად დასმული კითხვები</h2><h3>რა ზომის მონიტორი ავირჩიო?</h3><p>მაგიდასთან, 60–80 სმ მანძილიდან, ყველაზე უნივერსალურია 27": 2K გარჩევადობით ტექსტიც მკვეთრია და თამაშიც კომფორტული. მცირე მაგიდისა და ოფისისთვის 24" Full HD საკმარისია, ღრმა მაგიდაზე კი 32" 4K ან 34" ultrawide.</p><h3>რამდენი Hz მჭირდება?</h3><p>სამუშაოსა და ფილმებისთვის 60–100 Hz. თამაშისთვის მინიმუმ 144 Hz — სხვაობა 60 Hz-თან პირველივე წამიდან იგრძნობა. 240–360 Hz სწრაფი შუტერებისთვისაა და ძლიერ ვიდეობარათს მოითხოვს.</p><h3>IPS, VA თუ OLED?</h3><p>IPS — ზუსტი ფერები, დიზაინისა და უნივერსალური გამოყენებისთვის. VA — მაღალი კონტრასტი ფილმებისა და მოხრილი ეკრანებისთვის. OLED — სრული შავი, უმაღლესი კონტრასტი და მყისიერი რეაგირება, თამაშისა და კინოსთვის საუკეთესო, მაგრამ უფრო ძვირია.</p><h3>როგორ შევუერთო მონიტორი ლეპტოპს?</h3><p>HDMI კაბელით — ის თითქმის ყველა ლეპტოპს აქვს. თუ ლეპტოპსაც და მონიტორსაც USB-C (DisplayPort Alt Mode) აქვს, ერთი კაბელით გადაეცემა გამოსახულებაც, ხმაც და დატენვაც.</p><h3>27-დიუმიან მონიტორზე 2K ჯობია თუ 4K?</h3><p>თამაშისთვის 27"-ზე 2K ჯობია: მაღალ Hz-ს უფრო ადვილად მიიღებთ და ვიდეობარათსაც ნაკლებად ტვირთავს. ფოტოს, ვიდეოსა და ტექსტთან სამუშაოდ 4K უფრო მკვეთრ გამოსახულებას იძლევა.</p><h3>შემიძლია ნაწილ-ნაწილ ყიდვა?</h3><p>დიახ, Superi.ge-ზე მონიტორის შეძენა შეგიძლიათ ნაწილ-ნაწილ გადახდით. თბილისში მიწოდება უფასოა 100₾-დან, ასევე ვაწვდით მთელ საქართველოში.</p>' WHERE cd.lang_code = 'ka';
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'monitor' SET cd.meta_description = 'მონიტორები 22–57": გეიმინგ 144–360 Hz, 2K და 4K, OLED და მოხრილი — Samsung, LG, Dell, ASUS, Lenovo. ✓ ნაწილ-ნაწილ გადახდა ✓ მიწოდება' WHERE cd.lang_code = 'ka';

-- 2-3) პროდუქტები: სახელი, სათაური (მხოლოდ სადაც სახელის ასლი იყო), მეტა აღწერა
DROP TEMPORARY TABLE IF EXISTS tmp_m42;
CREATE TEMPORARY TABLE tmp_m42 AS SELECT s.name AS slug, pd.product AS new_name, pd.meta_description AS new_meta FROM cscart_seo_names s JOIN cscart_product_descriptions pd ON pd.product_id = s.object_id LIMIT 0;
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m42 t ON t.slug = s.name SET pd.page_title = CASE WHEN REPLACE(pd.page_title, ' ', '') = REPLACE(pd.product, ' ', '') THEN t.new_name WHEN REPLACE(pd.page_title, ' ', '') = CONCAT(REPLACE(pd.product, ' ', ''), '|Superi.ge') THEN CONCAT(t.new_name, ' | Superi.ge') ELSE pd.page_title END WHERE pd.lang_code = 'ka' AND IFNULL(pd.page_title, '') <> '';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m42 t ON t.slug = s.name SET pd.product = t.new_name WHERE pd.lang_code = 'ka';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m42 t ON t.slug = s.name SET pd.meta_description = t.new_meta WHERE pd.lang_code = 'ka';

-- 4) აღწერების გასწორება
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(pd.full_description, 'გაფართოება: 4K UHD (3440 x 1440)', 'გაფართოება: UWQHD (3440 x 1440)') WHERE pd.lang_code = 'ka' AND s.name IN ('samsung-odyssey-g8-ls34bg850sixci-34') AND pd.full_description LIKE '%გაფართოება: 4K UHD (3440 x 1440)%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(pd.full_description, 'პანელის ტიპი: VA', 'პანელის ტიპი: QD-OLED') WHERE pd.lang_code = 'ka' AND s.name IN ('samsung-odyssey-g8-ls34bg850sixci-34') AND pd.full_description LIKE '%პანელის ტიპი: VA%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(pd.full_description, 'გარჩევადობა: 4K 3440 × 1440', 'გარჩევადობა: 3440 × 1440') WHERE pd.lang_code = 'ka' AND s.name IN ('xiaomi-curved-gaming-monitor-g34wqi-34-c34wqba-rggl') AND pd.full_description LIKE '%გარჩევადობა: 4K 3440 × 1440%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(pd.full_description, 'ეკრანის ტიპი: მოსახედი პანელი', 'ეკრანის ტიპი: მოხრილი VA პანელი (1500R)') WHERE pd.lang_code = 'ka' AND s.name IN ('xiaomi-curved-gaming-monitor-g34wqi-34-c34wqba-rggl') AND pd.full_description LIKE '%ეკრანის ტიპი: მოსახედი პანელი%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(pd.full_description, 'განახლების სიხშირე: 144 Hz', 'განახლების სიხშირე: 240 Hz') WHERE pd.lang_code = 'ka' AND s.name IN ('samsung-odyssey-g4-ls27bg400eixci-27') AND pd.full_description LIKE '%განახლების სიხშირე: 144 Hz%';

-- 5) მისამართები: ძველი 301-ით გადადის ახალზე (თუ ახალი მისამართი თავისუფალია)
DROP TEMPORARY TABLE IF EXISTS tmp_slug42;
CREATE TEMPORARY TABLE tmp_slug42 AS SELECT object_id AS pid, name AS old_name, name AS new_name FROM cscart_seo_names LIMIT 0;
ALTER TABLE tmp_slug42 ADD COLUMN ok TINYINT NOT NULL DEFAULT 0;
UPDATE tmp_slug42 t JOIN cscart_seo_names s ON s.name = t.old_name AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET t.pid = s.object_id;
UPDATE tmp_slug42 t SET t.ok = 1 WHERE t.pid > 0 AND NOT EXISTS (SELECT 1 FROM cscart_seo_names s2 WHERE s2.name = t.new_name);
UPDATE tmp_slug42 t JOIN cscart_seo_names s ON s.name = t.new_name AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET t.pid = s.object_id, t.ok = 2 WHERE t.ok = 0 AND t.pid = 0;
DELETE r FROM cscart_seo_redirects r JOIN tmp_slug42 t ON TRIM(BOTH '/' FROM r.src) = t.new_name AND t.ok = 1 WHERE r.company_id = 1;
UPDATE cscart_seo_names s JOIN tmp_slug42 t ON t.pid = s.object_id AND t.old_name = s.name AND t.ok = 1 SET s.name = t.new_name WHERE s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1;

-- 6) ძებნის სინონიმები (იგივე JSON ფორმატი, რაც 35/38/40-ში)
-- მონიტორი  ←  მონიტორები, monitori, monitorebi, монитор, კომპიუტერის მონიტორი, კომპიუტერის ეკრანი
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'მონიტორი' ORDER BY synonym_id LIMIT 1);
-- გეიმინგ მონიტორი  ←  გეიმერული მონიტორი, სათამაშო მონიტორი, gaming monitor, игровой монитор, 144hz მონიტორი
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'გეიმინგ მონიტორი' ORDER BY synonym_id LIMIT 1);
-- მოხრილი მონიტორი  ←  მრუდე მონიტორი, curved მონიტორი, curved monitor, изогнутый монитор, ultrawide
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'მოხრილი მონიტორი' ORDER BY synonym_id LIMIT 1);

-- 7) ბრენდი „ACER “ → „ACER“
UPDATE cscart_product_feature_variant_descriptions SET variant = 'ACER' WHERE TRIM(variant) = 'ACER' AND CHAR_LENGTH(variant) > 4;

-- 8) ბმულები მოკლე აღწერაში — პირდაპირ სწორ მისამართზე
UPDATE cscart_product_descriptions pd SET pd.short_description = REPLACE(pd.short_description, 'href="https://SUPERI.GE/BOSCH"', 'href="https://superi.ge/bosch/"') WHERE pd.lang_code = 'ka' AND pd.short_description LIKE '%href="https://SUPERI.GE/BOSCH"%';
UPDATE cscart_product_descriptions pd SET pd.short_description = REPLACE(pd.short_description, 'href="https://superi.ge/intex"', 'href="https://superi.ge/intex/"') WHERE pd.lang_code = 'ka' AND pd.short_description LIKE '%href="https://superi.ge/intex"%';

-- 9) შემოწმება
SELECT s.name AS slug, cd.category, CHAR_LENGTH(REGEXP_REPLACE(IFNULL(cd.description, ''), '<[^>]*>', '')) AS text_chars, CHAR_LENGTH(cd.meta_description) AS meta_chars FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'monitor' WHERE cd.lang_code = 'ka';
SELECT COUNT(DISTINCT pd.product_id) AS products, SUM(pd.product LIKE 'მონიტორი %') AS named, SUM(pd.meta_description LIKE 'მონიტორი %') AS new_metas, MAX(CHAR_LENGTH(pd.meta_description)) AS max_meta_chars FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m42 t ON t.slug = s.name WHERE pd.lang_code = 'ka';
SELECT t.old_name, t.new_name, CASE t.ok WHEN 1 THEN 'გადაკეთდა' WHEN 2 THEN 'უკვე გაკეთებულია' ELSE 'გამოტოვდა' END AS result FROM tmp_slug42 t;
SELECT (SELECT COUNT(*) FROM cscart_product_descriptions WHERE lang_code = 'ka' AND (short_description LIKE '%href="https://SUPERI.GE/BOSCH"%' OR short_description LIKE '%href="https://superi.ge/intex"%')) AS old_links_left, (SELECT COUNT(*) FROM cscart_product_feature_variant_descriptions WHERE TRIM(variant) = 'ACER' AND CHAR_LENGTH(variant) > 4) AS acer_space_left;
SELECT phrase, synonyms FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase IN ('მონიტორი', 'გეიმინგ მონიტორი', 'მოხრილი მონიტორი');
DROP TEMPORARY TABLE IF EXISTS tmp_slug42;
DROP TEMPORARY TABLE IF EXISTS tmp_m42;

